from hypothesis import strategies as st

MOD = 998244353

@st.composite
def gen(draw):
    n = draw(st.integers(2, 5))
    q = draw(st.integers(1, 7))
    vmax = draw(st.sampled_from([1, 2, 3, 5, 10]))
    ops = []
    for _ in range(q):
        p = draw(st.integers(1, n))
        v = draw(st.integers(1, vmax))
        ops.append((p, v))
    lines = [f"{n} {q}"] + [f"{p} {v}" for p, v in ops]
    return "\n".join(lines) + "\n"

def _parse(inp):
    t = inp.split()
    n, q = int(t[0]), int(t[1])
    pairs = []
    idx = 2
    for _ in range(q):
        pairs.append((int(t[idx]), int(t[idx + 1])))
        idx += 2
    return n, q, pairs

def validate(inp):
    try:
        t = inp.split()
        if len(t) < 2:
            return False
        n, q = int(t[0]), int(t[1])
        if not (2 <= n <= 5000 and 1 <= q <= 5000):
            return False
        if len(t) != 2 + 2 * q:
            return False
        idx = 2
        for _ in range(q):
            p, v = int(t[idx]), int(t[idx + 1])
            idx += 2
            if not (1 <= p <= n and 1 <= v <= 10**9):
                return False
        return True
    except Exception:
        return False

def ref(inp):
    n, q, pairs = _parse(inp)
    count = 0
    # Enumerate every sequence of choices: bit i = 0 -> prefix, 1 -> suffix.
    for mask in range(1 << q):
        S = [0] * n
        ok = True
        for i, (p, v) in enumerate(pairs):
            if (mask >> i) & 1 == 0:
                # prefix S_1..S_p -> indices 0..p-1
                rng = range(0, p)
            else:
                # suffix S_p..S_N -> indices p-1..n-1
                rng = range(p - 1, n)
            if any(S[k] > v for k in rng):
                ok = False
                break
            for k in rng:
                S[k] = v
        if ok:
            count += 1
    return str(count % MOD)
